const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  const get = (obj) => new Promise((resolve, reject) => obj.evaluate(resolve, reject));

  // 1. Geometry & Time Definitions
  const date1 = '2021-12-14';
  const date2 = '2022-01-07';
  const iran = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017').filter(ee.Filter.eq('country_na', 'Iran'));
  const southRect = ee.Geometry.Rectangle([44.0, 24.0, 63.5, 31.5], null, false);
  const area = iran.geometry().intersection(southRect, ee.ErrorMargin(1000));

  // Total region pixel count at 1 km
  const totalPix = await get(ee.Image(1).reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: area,
    scale: 1000,
    maxPixels: 1e12
  }).get('constant'));
  console.log(`Region pixels (1km): ${totalPix}`);

  async function getS1VVdBMedian(dateStr) {
    async function attempt(windowDays) {
      const start = ee.Date(dateStr).advance(-windowDays, 'day');
      const end = ee.Date(dateStr).advance(windowDays + 1, 'day');
      let col = ee.ImageCollection('COPERNICUS/S1_GRD')
        .filterBounds(area)
        .filterDate(start, end)
        .filter(ee.Filter.eq('instrumentMode', 'IW'))
        .filter(ee.Filter.listContains('transmitterReceiverPolarisation', 'VV'));
      const count = await get(col.size());
      if (!count || count === 0) return { image: null, count: 0, windowDays };
      const med = ee.Image(col.median().select('VV'));
      const vvMask = med.gt(0);
      const vvdb = med.where(med.lte(0), 1e-6).log10().multiply(10).rename('VVdB').updateMask(vvMask);
      return { image: vvdb, count, windowDays };
    }
    let res = await attempt(3);
    if (res.count === 0) res = await attempt(7);
    return res;
  }

  async function getS2NDWIMedian(dateStr) {
    async function attempt(windowDays) {
      const start = ee.Date(dateStr).advance(-windowDays, 'day');
      const end = ee.Date(dateStr).advance(windowDays + 1, 'day');
      let col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
        .filterBounds(area)
        .filterDate(start, end)
        .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80))
        .map(function (img) {
          const qa = img.select('QA60');
          const cloud = qa.bitwiseAnd(1 << 10).neq(0).or(qa.bitwiseAnd(1 << 11).neq(0));
          const mask = cloud.not();
          return img.updateMask(mask).select(['B3', 'B8']).divide(10000).copyProperties(img, img.propertyNames());
        });
      const count = await get(col.size());
      if (!count || count === 0) return { image: null, count: 0, windowDays };
      const med = ee.Image(col.median()).rename(['green', 'nir']);
      const ndwi = med.expression('(g - n) / (g + n)', { g: med.select('green'), n: med.select('nir') })
        .rename('ndwi')
        .updateMask(med.select('green').mask().and(med.select('nir').mask()));
      return { image: ndwi, count, windowDays };
    }
    let res = await attempt(3);
    if (res.count === 0) res = await attempt(7);
    return res;
  }

  try {
    // Try Sentinel-1 first
    const s1d1 = await getS1VVdBMedian(date1);
    const s1d2 = await getS1VVdBMedian(date2);

    let source = null;
    let img1 = null;
    let img2 = null;
    let imgs1 = 0;
    let imgs2 = 0;

    if (s1d1.count > 0 && s1d2.count > 0) {
      source = 'Sentinel-1';
      img1 = s1d1.image; // VVdB
      img2 = s1d2.image;
      imgs1 = s1d1.count;
      imgs2 = s1d2.count;
    } else {
      // Fallback to Sentinel-2
      const s2d1 = await getS2NDWIMedian(date1);
      const s2d2 = await getS2NDWIMedian(date2);
      if (s2d1.count === 0 || s2d2.count === 0) {
        console.log(`Images ${date1}: ${s1d1.count + s2d1.count}, ${date2}: ${s1d2.count + s2d2.count}`);
        console.log('C1: Empty Collection (No images found in date/location for one or both comparison points).');
        console.log('C1: Empty Collection');
        return;
      }
      source = 'Sentinel-2';
      img1 = s2d1.image; // NDWI
      img2 = s2d2.image;
      imgs1 = s2d1.count;
      imgs2 = s2d2.count;
    }

    console.log(`Using: ${source}`);
    console.log(`${date1} images: ${imgs1}, ${date2} images: ${imgs2}`);

    // Harmonize coverage: intersect valid masks of both images
    const mask1 = img1.mask().reduce(ee.Reducer.min()).gt(0);
    const mask2 = img2.mask().reduce(ee.Reducer.min()).gt(0);
    const validBoth = mask1.and(mask2);

    const validBothCount = await get(ee.Image(1).updateMask(validBoth).reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: area,
      scale: 1000,
      maxPixels: 1e12
    }).get('constant'));

    if (!validBothCount || validBothCount === 0) {
      console.log('Valid pixels after masking (both dates): 0');
      console.log('C2: No Valid Pixels');
      return;
    }
    const validFrac = totalPix ? (100.0 * validBothCount / totalPix) : null;
    console.log(`Valid pixels (both dates): ${validBothCount} (${validFrac !== null ? validFrac.toFixed(1) : 'NA'}%)`);

    // Water classification and area
    let water1, water2;
    if (source === 'Sentinel-1') {
      // VVdB water threshold
      water1 = img1.lt(-17.0).updateMask(validBoth);
      water2 = img2.lt(-17.0).updateMask(validBoth);
    } else {
      // Sentinel-2 NDWI water threshold
      water1 = img1.gt(0.3).updateMask(validBoth);
      water2 = img2.gt(0.3).updateMask(validBoth);
    }

    const areaKm2 = ee.Image.pixelArea().divide(1e6).rename('a');
    const wa1 = await get(water1.rename('w').multiply(areaKm2).reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: area,
      scale: 1000,
      maxPixels: 1e12
    }).get('w'));
    const wa2 = await get(water2.rename('w').multiply(areaKm2).reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: area,
      scale: 1000,
      maxPixels: 1e12
    }).get('w'));

    if (wa1 === null || wa2 === null || isNaN(wa1) || isNaN(wa2)) {
      console.log(`Water km2 ${date1}: ${wa1}, ${date2}: ${wa2}`);
      console.log('C3: Calculation Failure');
      return;
    }

    const diff = wa2 - wa1;
    console.log(`Water km2 - ${date1}: ${wa1.toFixed(1)}, ${date2}: ${wa2.toFixed(1)}`);
    console.log(`Diff km2 (D2 - D1): ${diff.toFixed(1)}`);

    // Decide answer
    const tol = 1.0; // km2 tolerance
    if (diff > tol) {
      console.log('A: Yes');
    } else {
      console.log('B: No');
    }
  } catch (err) {
    console.error('Error:', err);
    console.log('D: Error');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
